"""Add an '## Examples' list to concept pages, linking the annotated example pages that demonstrate them.

Usage: python -I tools/link_examples.py --brain <brain> [--max 8]

Reads <brain>/ingest/staging/examples-*.yaml (each example's `techniques` slugs), maps old slugs through
<brain>/ingest/slug-map.yaml, and rewrites a generated block on each concept page:
    ## Examples
    <!-- generated by tools/link_examples.py -->
    - [[example-page]]: hook type; story shape
Re-running replaces the block as needed. Protected wiki pages are skipped.
Navigation only: the example pages carry the citations.
"""
import argparse
import pathlib
import sys
import re

import yaml

sys.path.insert(0, str(pathlib.Path(__file__).resolve().parent))
import brainlib
import wiki_edits

MARK = "<!-- generated by tools/link_examples.py -->"


def main() -> None:
    ap = argparse.ArgumentParser()
    brainlib.add_brain_arg(ap)
    ap.add_argument("--max", type=int, default=8)
    a = ap.parse_args()
    brain = brainlib.brain_dir(a.brain)
    sm = brain / "ingest" / "slug-map.yaml"
    slug_map = (yaml.safe_load(sm.read_text(encoding="utf-8")) or {}) if sm.exists() else {}
    wiki = brain / "wiki"
    pages = {p.stem: p for p in brainlib.wiki_pages(brain) if "examples" not in p.parts and "sources" not in p.parts}
    example_pages = {p.stem for p in (wiki / "examples").glob("*.md")}
    by_concept: dict[str, list[tuple[str, str]]] = {}
    for f in sorted((brain / "ingest" / "staging").glob("examples-*.yaml")):
        for ex in (yaml.safe_load(f.read_text(encoding="utf-8")) or {}).get("examples") or []:
            page = ex.get("page")
            if page not in example_pages:
                continue
            label = "; ".join(str(x) for x in (ex.get("hook_type"), ex.get("story_shape")) if x)
            for t in ex.get("techniques") or []:
                t = slug_map.get(t, t)
                if t in pages:
                    by_concept.setdefault(t, [])
                    if page not in [p for p, _ in by_concept[t]]:
                        by_concept[t].append((page, label))
    written = {}
    protected = wiki_edits.protected_pages(brain)
    for slug, path in pages.items():
        name = path.relative_to(wiki).as_posix()
        if name in protected:
            print(f"skipped protected page: wiki/{name}")
            continue
        original = path.read_text(encoding="utf-8")
        text = re.sub(rf"\n## Examples\n{re.escape(MARK)}\n(?:- .*\n?)*", "", original)
        exs = by_concept.get(slug, [])[: a.max]
        if exs:
            text = text.rstrip() + "\n"
            block = "\n## Examples\n" + MARK + "\n" + "".join(f"- [[{p}]]: {lbl}\n" for p, lbl in exs)
            if "\n## Related" in text:
                text = text.replace("\n## Related", block + "\n## Related", 1)
            else:
                text = text + block
        if text != original:
            path.write_text(text, encoding="utf-8", newline="\n")
            written[name] = wiki_edits.hashes.digest_bytes(text.encode("utf-8"))
    wiki_edits.register_writes(brain, written)
    linked = {p for v in by_concept.values() for p, _ in v[: a.max]}
    print(f"updated Examples lists on {len(written)} concept pages; {len(linked)}/{len(example_pages)} example pages matched")


if __name__ == "__main__":
    main()
